package main

import (
	"encoding/json"
	"net/http"
	"os"
)

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	Stock int     `json:"stock"`
}

type ErrorResp struct {
	Error string `json:"error"`
}

var (
	products       = []Product{{ID: 1, Name: "Widget", Price: 9.99, Stock: 100}, {ID: 2, Name: "Gadget", Price: 19.99, Stock: 50}}
	nextProductID  = 3
)

func productsHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	switch r.Method {
	case "GET":
		json.NewEncoder(w).Encode(products)
	case "POST":
		var body struct {
			Name  string  `json:"name"`
			Price float64 `json:"price"`
			Stock int     `json:"stock"`
		}
		json.NewDecoder(r.Body).Decode(&body)
		if body.Name == "" {
			w.WriteHeader(http.StatusBadRequest)
			json.NewEncoder(w).Encode(ErrorResp{Error: "Name is required"})
			return
		}
		if body.Price <= 0 {
			w.WriteHeader(http.StatusBadRequest)
			json.NewEncoder(w).Encode(ErrorResp{Error: "Price must be positive"})
			return
		}
		p := Product{ID: nextProductID, Name: body.Name, Price: body.Price, Stock: body.Stock}
		nextProductID++
		products = append(products, p)
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(p)
	}
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	http.HandleFunc("/products", productsHandler)

	http.ListenAndServe(":"+port, nil)
}

