package main

import (
	"encoding/json"
	"net/http"
	"os"
	"strconv"
	"strings"
	"time"
)

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	Stock int     `json:"stock"`
}

type CartItem struct {
	ProductID int      `json:"productId"`
	Quantity  int      `json:"quantity"`
	Product   *Product `json:"product,omitempty"`
}

type OrderItem struct {
	ProductID int     `json:"productId"`
	Quantity  int     `json:"quantity"`
	Price     float64 `json:"price"`
}

type Order struct {
	ID        int         `json:"id"`
	Items     []OrderItem `json:"items"`
	Total     float64     `json:"total"`
	CreatedAt time.Time   `json:"createdAt"`
}

type ErrorResp struct {
	Error string `json:"error"`
}

var (
	products       = []Product{{ID: 1, Name: "Widget", Price: 9.99, Stock: 100}, {ID: 2, Name: "Gadget", Price: 19.99, Stock: 50}}
	nextProductID  = 3
	nextOrderID    = 1
	cart           []CartItem
	orders         []Order
)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	http.HandleFunc("/products", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(products)
	})

	http.HandleFunc("/cart/add", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		var body struct {
			ProductID int `json:"productId"`
			Quantity  int `json:"quantity"`
		}
		json.NewDecoder(r.Body).Decode(&body)
		if body.Quantity < 1 {
			body.Quantity = 1
		}
		found := false
		for i, item := range cart {
			if item.ProductID == body.ProductID {
				cart[i].Quantity += body.Quantity
				found = true
				break
			}
		}
		if !found {
			cart = append(cart, CartItem{ProductID: body.ProductID, Quantity: body.Quantity})
		}
		json.NewEncoder(w).Encode(cart)
	})

	http.HandleFunc("/cart", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		var enriched []CartItem
		for _, item := range cart {
			for _, p := range products {
				if p.ID == item.ProductID {
					item.Product = &p
					break
				}
			}
			enriched = append(enriched, item)
		}
		json.NewEncoder(w).Encode(enriched)
	})

	http.HandleFunc("/orders", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method == "POST" {
			var items []OrderItem
			total := 0.0
			for _, item := range cart {
				for _, p := range products {
					if p.ID == item.ProductID {
						items = append(items, OrderItem{ProductID: item.ProductID, Quantity: item.Quantity, Price: p.Price})
						total += p.Price * float64(item.Quantity)
						break
					}
				}
			}
			order := Order{ID: nextOrderID, Items: items, Total: total, CreatedAt: time.Now()}
			nextOrderID++
			orders = append(orders, order)
			cart = nil
			w.WriteHeader(http.StatusCreated)
			json.NewEncoder(w).Encode(order)
		}
	})

	http.HandleFunc("/orders/", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		idStr := strings.TrimPrefix(r.URL.Path, "/orders/")
		id, err := strconv.Atoi(idStr)
		if err != nil {
			http.NotFound(w, r)
			return
		}
		for _, o := range orders {
			if o.ID == id {
				json.NewEncoder(w).Encode(o)
				return
			}
		}
		http.NotFound(w, r)
	})

	http.ListenAndServe(":"+port, nil)
}
